// Builds rebuilt.html from the Specimen capture of section 4.
// Usage: node build.mjs <capture-root>
import fs from "node:fs";
import path from "node:path";

const root = process.argv[2];
const src = fs.readFileSync(
  path.join(root, "bundle/sections/04-the-easiest-way-to-train-your-mo/04-the-easiest-way-to-train-your-mo.html"),
  "utf8",
);

// Page geometry from bundle/manifest.json (desktop): section 4 at y=1005, 1140 tall; footer ends at 6467+930.
const SECTION_TOP = 1005;
const SECTION_H = 1140;
const PAGE_H = 6467 + 930;

// Elements whose transform/opacity the motion below drives: strip their frozen values.
const ANIMATED = new Set(["c2", "c10", "c164", "c15", "c17", "c19", "c20", "c146", "c147", "c149", "c151", "c153", "c163", "c9"]);
const MOTION_PROPS = new Set(["transform", "translate", "scale", "rotate", "opacity", "transition", "transition-property", "transition-duration", "transition-timing-function", "transition-delay", "will-change"]);

// Computed-style noise: logical duplicates of physical properties and colour echoes.
const DROP = [
  /^block-size$/, /^inline-size$/, /^(min|max)-(block|inline)-size$/,
  /^border-(block|inline)/, /^(margin|padding|inset)-(block|inline)/,
  /^caret-color$/, /^column-rule-color$/, /^row-rule-color$/, /^text-emphasis-color$/,
  /^text-decoration-color$/, /^tab-size$/, /^text-size-adjust$/, /^outline-color$/,
  /^-webkit-locale$/, /^-webkit-tap-highlight-color$/, /^-webkit-text-stroke-color$/,
  /^-webkit-text-fill-color$/, /^-webkit-border-/, /^-webkit-column-/,
];

function splitDecls(body) {
  // split on ; not inside parentheses or quotes
  const out = [];
  let depth = 0, q = null, cur = "";
  for (const ch of body) {
    if (q) { if (ch === q) q = null; cur += ch; continue; }
    if (ch === '"' || ch === "'") { q = ch; cur += ch; continue; }
    if (ch === "(") depth++;
    if (ch === ")") depth--;
    if (ch === ";" && depth === 0) { out.push(cur); cur = ""; continue; }
    cur += ch;
  }
  if (cur.trim()) out.push(cur);
  return out;
}

const rules = [];
for (const m of src.matchAll(/^\.(c\d+)\{(.*)\}$/gm)) {
  const [, cls, body] = m;
  const decls = splitDecls(body).filter((d) => {
    const prop = d.slice(0, d.indexOf(":")).trim();
    if (DROP.some((r) => r.test(prop))) return false;
    if (prop === "perspective-origin" && !/(^|;)perspective:/.test(body)) return false;
    if (ANIMATED.has(cls) && MOTION_PROPS.has(prop)) return false;
    return true;
  });
  rules.push(`.${cls}{${decls.join(";")}}`);
}

let markup = src.slice(src.indexOf("<body>") + 6, src.indexOf("</body>"));
markup = markup.replaceAll("../../assets/", "bundle/assets/");
const css = rules.join("\n").replaceAll("../../assets/", "bundle/assets/");

const A = "bundle/assets/";
const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>The easiest way to train your models</title>
<style>
@font-face{font-family:beltram;src:url("${A}BeltramTest_Regular-s-p-3f0fgixy9p343-80525892.woff2") format("woff2");font-weight:400;font-display:swap}
@font-face{font-family:beltram;src:url("${A}BeltramTest_Medium-s-p-3btn377t5x7dq-43bb960b.woff2") format("woff2");font-weight:500;font-display:swap}
@font-face{font-family:beltram;src:url("${A}BeltramTest_Bold-s-p-1rlo4atrytbgg-05820e08.woff2") format("woff2");font-weight:700;font-display:swap}
@font-face{font-family:"beltram Fallback";src:local("Arial");ascent-override:103.64%;descent-override:37.23%;line-gap-override:0%;size-adjust:99.38%}
@font-face{font-family:inter;src:url("${A}Inter_600-s-2dov6rjg62vru-2ea919e1.woff2") format("woff2");font-weight:600;font-display:swap}
@font-face{font-family:"inter Fallback";src:local("Arial");ascent-override:87.91%;descent-override:21.89%;line-gap-override:0%;size-adjust:110.2%}

/* Page: the section sits where it does on the original page, and the page is as tall as the original. */
html{background:#fff}
body{margin:0;background:#fff;width:1425px;min-height:${PAGE_H}px}
.page-top{height:${SECTION_TOP}px}
.page-bottom{height:${PAGE_H - SECTION_TOP - SECTION_H}px}
*,::before,::after{border-width:0;box-sizing:border-box}

/* Layout and look: the page's computed styles, as captured. */
${css}

/* ---- Motion (DESIGN.md "Motion" and "Effect code", section 4) ---- */

/* Watch it in action: hover */
#platform > div > div:nth-of-type(1) > div:nth-of-type(2) > a{transition:scale 300ms cubic-bezier(0.34, 1.56, 0.64, 1)}
#platform > div > div:nth-of-type(1) > div:nth-of-type(2) > a:hover{scale:1.05}
#platform > div > div:nth-of-type(1) > div:nth-of-type(2) > a:focus-visible{outline:1px solid rgb(0, 95, 204);outline-offset:1px;box-shadow:0 0 0 2px oklab(0.36619 0.000957593 -0.00770146 / 0.5)}

/* pulse: the page's own keyframes and timing */
@keyframes pulse{
  0%{opacity:1;animation-timing-function:cubic-bezier(0.4, 0, 0.6, 1)}
  50%{opacity:0.5;animation-timing-function:cubic-bezier(0.4, 0, 0.6, 1)}
  100%{opacity:1;animation-timing-function:cubic-bezier(0.4, 0, 0.6, 1)}
}
#_r_7_ > div:nth-of-type(3) > div:nth-of-type(2) > div:nth-of-type(1) > div:nth-of-type(2) > div > div > span:nth-of-type(3) > span:nth-of-type(1) > span:nth-of-type(2) > span{animation:pulse 2000ms linear 0ms infinite normal none}

/* Scroll reveals (IntersectionObserver adds .is-visible) */
#platform > div > div:nth-of-type(1){opacity:0;transform:translate(0px, 24px);transition:opacity 608ms cubic-bezier(0.177, 0.911, 0.213, 1.015), transform 608ms cubic-bezier(0.177, 0.911, 0.213, 1.015)}
#platform > div > div:nth-of-type(2){opacity:0;transform:translate(0px, 24px);transition:opacity 621ms cubic-bezier(0.183, 0.875, 0.173, 1.022), transform 621ms cubic-bezier(0.183, 0.875, 0.173, 1.022)}
#platform > div > div:nth-of-type(3){opacity:0;transform:translate(0px, 24px);transition:opacity 609ms cubic-bezier(0.18, 0.819, 0.153, 1.03), transform 609ms cubic-bezier(0.18, 0.819, 0.153, 1.03)}
#platform > div > div.is-visible{opacity:1;transform:none}

@media (prefers-reduced-motion: reduce){
  #platform > div > div{opacity:1;transform:none;transition:none}
}
</style>
</head>
<body>
<div class="page-top" aria-hidden="true"></div>
${markup}
<div class="page-bottom" aria-hidden="true"></div>
<script>
(() => {
  // Scroll-linked motion. Values and page-scroll ranges exactly as DESIGN.md records them:
  // translate/opacity over 427-1151px, scale over 429-1152px, all linear.
  // The tilted panels (div 3 and div 7) go from the recorded matrix3d
  // = perspective(1800px) translate3d(0, y, z) scale(0.88) rotateX(26deg)
  // to the recorded end matrix3d = perspective(1800px) translate3d(0, 0, z).
  const T = [427, 1151], S = [429, 1152];
  const q = (s) => document.querySelector("#_r_7_ > " + s);
  const els = {
    d1: q("div:nth-of-type(1)"),
    d2: q("div:nth-of-type(2)"),
    d3: q("div:nth-of-type(3)"),
    d3glow: q("div:nth-of-type(3) > div:nth-of-type(1)"),
    d3sheen: q("div:nth-of-type(3) > div:nth-of-type(2) > div:nth-of-type(2)"),
    d4: q("div:nth-of-type(4)"),
    d5: q("div:nth-of-type(5)"),
    d6: q("div:nth-of-type(6)"),
    d7: q("div:nth-of-type(7)"),
    d7sheen: q("div:nth-of-type(7) > div > div:nth-of-type(2)"),
  };
  const p = (y, [a, b]) => Math.min(1, Math.max(0, (y - a) / (b - a)));
  const lerp = (from, to, t) => from + (to - from) * t;
  const tilt = (y, z, t, s) =>
    "perspective(1800px) translate3d(0px," + lerp(y, 0, t) + "px," + z + "px) scale(" + lerp(0.88, 1, s) + ") rotateX(" + lerp(26, 0, t) + "deg)";

  function update() {
    const y = window.scrollY, t = p(y, T), s = p(y, S);
    els.d1.style.transform = "translateY(" + lerp(5.13281, 0, t) + "px)";
    els.d2.style.transform = "translateY(" + lerp(6.87, 0, t) + "px)";
    els.d3.style.transform = tilt(67.1594, 0, t, s);
    els.d3glow.style.transform = "translateY(" + lerp(54.3994, 24.1775, t) + "px) scale(" + lerp(1.08, 0.96, s) + ")";
    els.d3glow.style.opacity = lerp(0.22, 0.42, t);
    els.d3sheen.style.transform = "translateY(" + lerp(-482.108, 0, t) + "px)";
    els.d3sheen.style.opacity = lerp(0.55, 0, t);
    els.d4.style.transform = "translateY(" + lerp(54.2506, 0, t) + "px)";
    els.d5.style.transform = "translateY(" + lerp(90.9125, 0, t) + "px)";
    els.d6.style.transform = "translateY(" + lerp(39.4552, 0, t) + "px)";
    els.d7.style.transform = tilt(68.0875, 80, t, s);
    els.d7sheen.style.transform = "translateY(" + lerp(-121.118, 0, t) + "px)";
    els.d7sheen.style.opacity = lerp(0.55, 0, t);
  }
  let queued = false;
  addEventListener("scroll", () => {
    if (!queued) { queued = true; requestAnimationFrame(() => { queued = false; update(); }); }
  }, { passive: true });
  update();

  // Reveals: play once when the block's top passes 85% of the viewport.
  const io = new IntersectionObserver((entries) => {
    for (const e of entries) if (e.isIntersecting) { e.target.classList.add("is-visible"); io.unobserve(e.target); }
  }, { rootMargin: "0px 0px -15% 0px" });
  document.querySelectorAll("#platform > div > div").forEach((el) => io.observe(el));
})();
</script>
</body>
</html>
`;
fs.writeFileSync(path.join(root, "rebuilt.html"), html);
console.log("rules", rules.length, "css bytes", css.length, "html bytes", html.length);

